const menuBtn=document.getElementById('menuBtn'),drawer=document.getElementById('drawer'),drawerClose=document.getElementById('drawerClose');
function setDrawer(open){drawer.classList.toggle('open',open);drawer.setAttribute('aria-hidden',String(!open));menuBtn.setAttribute('aria-expanded',String(open));}
menuBtn.addEventListener('click',()=>setDrawer(true));drawerClose.addEventListener('click',()=>setDrawer(false));drawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setDrawer(false)));

const stageData={
 discovery:{title:'DISCOVERY',text:'First exposure to an athlete, team, league, sport, rivalry, storyline or piece of sports culture. The question is what makes somebody stop scrolling long enough to notice.'},
 engagement:{title:'ENGAGEMENT',text:'Watching, rewatching, liking, commenting, sharing, following, searching and choosing another piece of related content. One exposure becomes a pattern.'},
 participation:{title:'PARTICIPATION',text:'Posting reactions, creating edits, joining debates, playing fantasy, sharing memes or contributing to the community around the sport.'},
 identity:{title:'IDENTITY',text:'The shift from “I watch this” to “this is part of who I am.” Fans begin using team language, rituals, symbols and group membership to describe themselves.'},
 loyalty:{title:'LOYALTY',text:'Continued attention and attachment over time, including the ugly seasons. Digital engagement can contribute to loyalty, but it does not automatically create it.'}
};
const stageDetail=document.getElementById('stageDetail');
function showStage(key){const d=stageData[key];stageDetail.innerHTML=`<h3>${d.title}</h3><p>${d.text}</p>`;document.querySelectorAll('.stage').forEach(b=>b.classList.toggle('active',b.dataset.stage===key));}
document.querySelectorAll('.stage').forEach(b=>b.addEventListener('click',()=>showStage(b.dataset.stage)));showStage('discovery');

document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.getElementById('thenPanel').classList.toggle('hidden',btn.dataset.tab!=='then');document.getElementById('nowPanel').classList.toggle('hidden',btn.dataset.tab!=='now');}));

const plans={Discovery:{stage:'DISCOVERY',approach:'Lead with instantly understandable, high-context content that makes a stranger care before asking them to know the whole story.',metrics:'Qualified follows, repeat viewers, profile visits, branded search',risk:'A viral clip can create attention without creating attachment.'},Engagement:{stage:'ENGAGEMENT',approach:'Build recurring formats that reward the second, third and tenth view rather than treating every post like a one-off.',metrics:'Returning viewers, shares, comments, repeat watch behavior',risk:'High engagement can still be shallow or personality-first.'},Participation:{stage:'PARTICIPATION',approach:'Give fans something to do: react, predict, remix, debate, create or contribute.',metrics:'UGC volume, comment quality, community activity, shares',risk:'Participation is not automatically loyalty.'},Community:{stage:'PARTICIPATION → IDENTITY',approach:'Create recurring language, rituals and social spaces fans can recognize as theirs.',metrics:'Repeat contributors, community retention, fan-created rituals',risk:'Forced community language feels manufactured.'},Identity:{stage:'IDENTITY',approach:'Connect content to symbols, stories, history and belonging that fans can carry into their own self-description.',metrics:'Repeat engagement, branded language use, community signals',risk:'Identity cannot be rushed with a single campaign.'},Loyalty:{stage:'LOYALTY',approach:'Reward continuity. Give fans reasons to stay when novelty is gone and the team is not winning.',metrics:'Retention, repeat viewing, repeat attendance or purchase behavior',risk:'Loyalty is a long-term outcome, not a content KPI.'},'Game viewership':{stage:'ENGAGEMENT → PARTICIPATION',approach:'Use short-form content as the bridge into a larger appointment: give context, stakes, personalities and reasons to watch live.',metrics:'Link clicks, tune-in intent, repeat game-content viewers',risk:'Views do not prove game conversion without measurement.'},Attendance:{stage:'IDENTITY → LOYALTY',approach:'Make the in-person experience feel like the next chapter of the digital relationship, not a completely separate product.',metrics:'Ticket intent, tracked offers, first-time buyers, repeat attendance',risk:'Do not infer ticket conversion from content views alone.'},'Merchandise consideration':{stage:'IDENTITY → LOYALTY',approach:'Merch works best when it represents belonging, player attachment or a story fans already care about.',metrics:'Product page visits, tracked clicks, add-to-cart, conversion',risk:'A like is not purchase intent.'}};
document.getElementById('buildBtn').addEventListener('click',()=>{const org=document.getElementById('orgSelect').value,aud=document.getElementById('audienceSelect').value,goal=document.getElementById('goalSelect').value,content=document.getElementById('contentSelect').value,p=plans[goal]||plans.Discovery;document.getElementById('gamePlan').innerHTML=`<div class="plan-kicker">YOUR GAME PLAN</div><h3>${p.stage}</h3><p><strong>${org}</strong> targeting <strong>${aud.toLowerCase()}</strong> with <strong>${content.toLowerCase()}</strong>.</p><div class="plan-grid"><div><b>CONTENT APPROACH</b>${p.approach}</div><div><b>USEFUL METRICS</b>${p.metrics}</div><div><b>WHAT NOT TO OBSESS OVER</b>Raw view count without evidence of movement deeper into the fan journey.</div><div><b>RISK</b>${p.risk}</div></div><p class="note" style="color:#aaa;margin-top:22px">Provisional strategy tool. Final recommendations will be updated when the thesis findings are complete.</p>`;});

const labData={
'Highlights':['DISCOVERY → ENGAGEMENT','People unfamiliar with the team or athlete','Low-friction entry point. A great play can make sense before the viewer knows the whole context.','The highlight can become bigger than the team.','Repeat viewers, follows, shares, profile visits'],
'Athlete personality':['DISCOVERY → IDENTITY','Player-first and younger fans','Personality gives people a human reason to care before they care about standings.','Attachment may stay with the athlete instead of transferring to the team.','Follows, comments, repeat viewers, athlete-to-team navigation'],
"Mic'd up":['ENGAGEMENT → PARTICIPATION','Existing and casual fans','Turns the game into character, humor and access.','Can become repetitive if it has no story.','Shares, completion, comments, repeat format viewers'],
'Behind the scenes':['ENGAGEMENT → IDENTITY','Casual and existing fans','Creates access that traditional broadcasts cannot always provide.','Access without a clear story can feel like filler.','Completion, saves, repeat viewers, comments'],
'Fan reactions':['PARTICIPATION → IDENTITY','Community-driven fans','Makes fans visible inside the product instead of treating them as the audience outside it.','Can overrepresent the loudest fans.','UGC, replies, shares, repeat contributors'],
'Memes':['ENGAGEMENT → PARTICIPATION','Highly social audiences','Fast cultural shorthand. Great for inside jokes and belonging.','Trying too hard is immediately visible.','Shares, comments, remix behavior'],
'History':['DISCOVERY → IDENTITY','New and existing fans','Lets new fans enter a tradition without needing decades of prior knowledge.','Too much context can feel like homework.','Saves, completion, follows, search behavior'],
'Nostalgia':['IDENTITY → LOYALTY','Existing and lapsed fans','Reconnects present fandom with memory and shared history.','Less useful for audiences with no prior attachment.','Shares, comments, return viewers'],
'Rivalries':['DISCOVERY → PARTICIPATION','Casual, existing and opposing fans','Instant stakes, conflict and identity language.','Can reward hostility more than healthy fandom.','Comments, shares, debate quality'],
'Educational content':['DISCOVERY → ENGAGEMENT','People unfamiliar with the sport','Reduces the barrier to entry and makes confusing rules or strategy approachable.','Can feel patronizing if overexplained.','Saves, completion, search, repeat viewers'],
'Creator collaborations':['DISCOVERY → PARTICIPATION','Fans who trust creators more than official accounts','Borrowed context and credibility can create a new doorway into the sport.','Creator fit matters more than follower count.','Qualified reach, creator audience overlap, follows'],
'UGC':['PARTICIPATION → IDENTITY','Active fan communities','Fans help build the story instead of only consuming it.','Quality and moderation can vary widely.','Submissions, shares, repeat contributors'],
'Storytelling':['ENGAGEMENT → IDENTITY','Fans who need context and stakes','Turns isolated clips into narratives people want to follow over time.','Weak hooks can lose short-form audiences quickly.','Series completion, repeat viewers, follows'],
'Trends':['DISCOVERY','Broad algorithmic audiences','Can place sports content inside a wider cultural conversation.','Trend-first content can be forgettable and interchangeable.','Qualified reach, profile visits, follows']};
function showLab(name){const d=labData[name];document.getElementById('labCard').innerHTML=`<div class="eyebrow">CONTENT LAB / ${name.toUpperCase()}</div><h3>${name}</h3><div class="lab-details"><div><b>BEST FAN STAGE</b>${d[0]}</div><div><b>POTENTIAL AUDIENCE</b>${d[1]}</div><div><b>WHY IT COULD WORK</b>${d[2]}</div><div><b>POTENTIAL DOWNSIDE</b>${d[3]}</div><div><b>USEFUL METRICS</b>${d[4]}</div><div><b>RESEARCH SUPPORT</b>Placeholder until thesis evidence is supplied.</div></div>`;document.querySelectorAll('#labMenu button').forEach(b=>b.classList.toggle('active',b.dataset.format===name));}
document.querySelectorAll('#labMenu button').forEach(b=>b.addEventListener('click',()=>showLab(b.dataset.format)));showLab('Highlights');

document.querySelectorAll('.player').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('xiPanel').innerHTML=`<strong>${String(btn.dataset.player).padStart(2,'0')} — RESEARCH FINDING</strong><p><b>THE PRINCIPLE:</b> Waiting for the final research-supported recommendation.</p><p><b>WHAT THE RESEARCH FOUND:</b> Waiting for John’s research data.</p><p><b>JG’S TAKE:</b> This roster spot stays open until the evidence earns it.</p>`;}));
